exercises.solutionCode:
func calculate_total(item_price, item_count, discount_percent):
    var subtotal = item_price * item_count
    return int(subtotal * (100 - discount_percent) / 100)

var total = calculate_total(item_price, item_count, discount_percent)
if player_gold >= total:
    print("Purchased: " + str(total) + " | Gold left: " + str(player_gold - total))
else:
    print("Not enough gold: " + str(total))
